package_files = [*ROOT.glob('*.html')]
package_files += [ROOT / name for name in ['styles.css', 'refinement.css', 'app.js', 'fonts.css', 'robots.txt', 'sitemap.xml', 'assets/favicon.svg', 'assets/metehan-portre.jpg', 'assets/metehan-cakal.jpg']]
